const inputData = $input.first().json;

const historialPrevio = inputData.historial_sesion || [];
const nuevoMensaje = `Usuario: ${inputData.message}\nAgente: ${inputData.respuesta}`;
historialPrevio.push(nuevoMensaje);

return [{
  json: {
    user_id: inputData.user_id,
    historial_sesion: historialPrevio,
    ultima_respuesta: inputData.respuesta
  }
}];

const catalog = $input.first().json.catalog;
const groupedItems = catalog.reduce((acc, item) => {
  const title = item.producto;
  const category = item.categoria;
  const sku = item.sku;
  const color = item.color;
  if (!acc[category]){
    acc[category] = { categoria: category, productos: []}
  }
  let product = acc[category].productos.find((prod) => prod.titulo === title);

  if (!product) {
    product = { titulo: title, skus: [] };
    acc[category].productos.push(product);
  }

   product.skus.push({ titulo:sku, color: color });
  return acc;
}, {});

const result = Object.values(groupedItems);
return result.map((item) => ({ json: item }));

const products = $('uso imagen producto').first().json.output.catalog[0].productos
const folders = $('Productos categoria').all();

const result = products.map((item, index) => {
  const tittle = item.titulo.toUpperCase();
  const folderMatch = folders.find(x => x.json.name === tittle);

  return {
    json: {
      titulo: tittle,
      idFolder: folderMatch ? folderMatch.json.id : null,
      paired: !!folderMatch
    },
    pairedItem: {
      item: index
    }
};
});

return result;
